309		public override int PitToTileSetIDSubFunction(TileGrid tileGrid, int tileRow, int tileCol, int pitTilesAbove = 0, int pitTilesBelow = 0)
310		{
311			if (pitTilesAbove == 0 && pitTilesBelow == 0)
312			{
313				return platformTopWallTiles.GetRandomValue();
314			}
315			MapOrdinalDirections mapOrdinalDirections = TileSet.CheckAdjacentTiles(tileRow, tileCol, tileGrid, (Tile t) => t.terrain == Tile.TerrainType.Pit);
316			switch (pitTilesAbove)
317			{
318			case 0:
319				if (AdjTileTest.WallNorth.Test(tileGrid, tileRow, tileCol))
320				{
321					return platformWallTransitionTiles.GetRandomValue();
322				}
323				return platformTopWallTiles.GetRandomValue();
324			case 1:
325				return platformMidWallTiles.GetRandomValue();
326			case 2:
327				return platformLowerWallTiles.GetRandomValue();
328			default:
329			{
330				MapOrdinalDirections mapOrdinalDirections2 = MapOrdinalDirections.None;
331				if (tileGrid.IsValidTile(tileRow - 1, tileCol))
332				{
333					mapOrdinalDirections2 = TileSet.CheckAdjacentTiles(tileRow - 1, tileCol, tileGrid, (Tile t) => t.terrain == Tile.TerrainType.Pit);
334				}
335				bool flag = !mapOrdinalDirections2.HasFlag(MapOrdinalDirections.East) && !mapOrdinalDirections2.HasFlag(MapOrdinalDirections.NorthEast);
336				bool flag2 = !mapOrdinalDirections2.HasFlag(MapOrdinalDirections.West) && !mapOrdinalDirections2.HasFlag(MapOrdinalDirections.NorthWest);
337				if (pitTilesAbove == 3)
338				{
339					if (flag && !mapOrdinalDirections.HasFlag(MapOrdinalDirections.East))
340					{
341						return platformPitTopRightCornerTile;
342					}
343					if (flag2 && !mapOrdinalDirections.HasFlag(MapOrdinalDirections.West))
344					{
345						return platformPitTopLeftCornerTile;
346					}
347					return platformPitTransitionTiles.GetRandomValue();
348				}
349				bool flag3 = tileGrid.IsValidTile(tileRow - 3, tileCol + 1) && (tileGrid[tileRow - 3, tileCol + 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow - 3, tileCol + 1].overlay != Tile.OverlayType.None);
350				if (tileGrid.IsValidTile(tileRow - 3, tileCol - 1) && (tileGrid[tileRow - 3, tileCol - 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow - 3, tileCol - 1].overlay != Tile.OverlayType.None))
351				{
352					return pitLeftWallTiles.GetRandomValue();
353				}
354				if (flag3)
355				{
356					return pitRightWallTiles.GetRandomValue();
357				}
358				int num = tileGrid.CountTilesInDir(tileRow, tileCol - 1, (Tile t) => t.terrain == Tile.TerrainType.Pit, MapOrdinalDirections.North, excludeFirstTile: false);
359				int num2 = tileGrid.CountTilesInDir(tileRow, tileCol + 1, (Tile t) => t.terrain == Tile.TerrainType.Pit, MapOrdinalDirections.North, excludeFirstTile: false);
360				if (pitTilesAbove > 3 && num2 == 4)
361				{
362					return platWallToPitBotLeftCornerTile;
363				}
364				if (pitTilesAbove > 3 && num == 4)
365				{
366					return platWallToPitBotRightCornerTile;
367				}
368				return pitTiles.GetRandomValue();
369			}
370			}
371		}
372	}
