using System.Collections.Generic;
public class CompositeTileGridTest : TileGridTest
{
	public List<TileGridTest> tests;
	public bool passIfAnyTrue = true;
	private bool _hasLastConditionalRow;
	private bool _hasLastConditionalCol;
	public override bool HasLastConditionalRow => _hasLastConditionalRow;
	public override bool HasLastConditionalCol => _hasLastConditionalCol;
	public CompositeTileGridTest(CompositeTileGridTest compositeTileGridTest)
	{
		tests = compositeTileGridTest.tests;
		passIfAnyTrue = compositeTileGridTest.passIfAnyTrue;
		_hasLastConditionalCol = compositeTileGridTest.HasLastConditionalCol;
		_hasLastConditionalRow = compositeTileGridTest.HasLastConditionalRow;
	}
	public CompositeTileGridTest()
	{
		tests = new List<TileGridTest>();
	}
	public void Add(TileGridTest tileGridTest)
	{
		tests.Add(tileGridTest);
		if (!HasLastConditionalRow && tileGridTest.HasLastConditionalRow)
		{
			_hasLastConditionalRow = true;
		}
		if (!HasLastConditionalCol && tileGridTest.HasLastConditionalCol)
		{
			_hasLastConditionalCol = true;
		}
	}
	public bool InternalOrTest(TileGrid grid, int row, int col, int rowOffset = 0, int colOffset = 0, int rowCount = 0, int colCount = 0)
	{
		for (int i = 0; i < tests.Count; i++)
		{
			if (tests[i].InternalTest(grid, row, col, rowOffset, colOffset, rowCount, colCount))
			{
				return true;
			}
		}
		return false;
	}
	public bool InternalAndTest(TileGrid grid, int row, int col, int rowOffset = 0, int colOffset = 0, int rowCount = 0, int colCount = 0)
	{
		for (int i = 0; i < tests.Count; i++)
		{
			if (!tests[i].InternalTest(grid, row, col, rowOffset, colOffset, rowCount, colCount))
			{
				return false;
			}
		}
		return true;
	}
	public override bool InternalTest(TileGrid grid, int row, int col, int rowOffset = 0, int colOffset = 0, int rowCount = 0, int colCount = 0)
	{
		if (passIfAnyTrue)
		{
			return InternalOrTest(grid, row, col, rowOffset, colOffset, rowCount, colCount);
		}
