415	public static class MeshGenerator
416	{
417		public static void GenerateMeshes(TileGrid tileGrid, Transform parentTrans = null, string forceTileSet = "", bool createChildContainer = true)
418		{
419			GameObject gameObject = parentTrans.gameObject;
420			if (createChildContainer)
421			{
422				gameObject = Globals.FindOrCreateGameObject("Meshes", parentTrans);
423				parentTrans = gameObject.transform;
424			}
425			List<GameObject> list = new List<GameObject>();
426			for (int i = 0; i < Tile.tileLayerNames.Length; i++)
427			{
428				Tuple<MeshFilter, MeshRenderer> tuple = CreateLayerMeshObj(Tile.tileLayerNames[i], parentTrans);
429				Tuple<Mesh, Material[]> tuple2 = CreateLayerMesh(tileGrid, Tile.tileLayerNames[i], forceTileSet);
430				tuple.First.sharedMesh = tuple2.First;
431				tuple.Second.materials = tuple2.Second;
432				list.Add(tuple.Second.gameObject);
433			}
434			StaticBatchingUtility.Combine(list.ToArray(), parentTrans.gameObject);
435		}
436		public static Tuple<Mesh, Material[]> CreateLayerMesh(TileGrid tileGrid, string tileLayerName, string forceTileSet = "")
437		{
438			Mesh mesh = new Mesh();
439			Dictionary<string, List<int>> dictionary = new Dictionary<string, List<int>>();
440			mesh.vertices = tileGrid.layerVertexData[tileLayerName].vertices;
441			mesh.triangles = InitTriangles(mesh.vertices.Length / 4);
442			mesh.normals = InitNormals(mesh.vertices.Length);
443			mesh.uv = InitUVs(tileGrid, tileLayerName, forceTileSet);
444			mesh.colors = InitColors(mesh.vertices.Length, tileGrid, tileLayerName);
445			InitSubMeshTriangles(tileGrid.layerVertexData[tileLayerName].subMeshIndices, dictionary);
446			List<Material> list = new List<Material>();
447			mesh.subMeshCount = tileGrid.layerVertexData[tileLayerName].tileSetNames.Count;
448			int num = 0;
449			foreach (string tileSetName in tileGrid.layerVertexData[tileLayerName].tileSetNames)
450			{
451				mesh.SetTriangles(dictionary[tileSetName].ToArray(), num);
452				list.Add(TileSet.GetTileSet(tileSetName).material);
453				num++;
454			}
455			return new Tuple<Mesh, Material[]>(mesh, list.ToArray());
456		}
457		public static Tuple<MeshFilter, MeshRenderer> CreateLayerMeshObj(string tileLayerName, Transform parentTrans)
458		{
459			GameObject gameObject = Globals.FindOrCreateGameObject(tileLayerName, parentTrans);
460			MeshFilter meshFilter = gameObject.GetComponent<MeshFilter>();
461			if (meshFilter == null)
462			{
463				meshFilter = gameObject.AddComponent<MeshFilter>();
464			}
465			if (meshFilter.sharedMesh != null)
466			{
467				meshFilter.sharedMesh.Clear();
468			}
469			MeshRenderer meshRenderer = gameObject.GetComponent<MeshRenderer>();
470			if (meshRenderer == null)
471			{
472				meshRenderer = gameObject.AddComponent<MeshRenderer>();
473			}
474			switch (tileLayerName)
475			{
476			case "Floor":
477				meshRenderer.sortingLayerName = "Default";
478				break;
479			case "Pit":
480				meshRenderer.sortingLayerName = "SubFloor";
481				meshRenderer.gameObject.layer = LayerMask.NameToLayer("Pit");
482				break;
483			case "Debug":
484				meshRenderer.sortingLayerName = "UI";
485				break;
486			default:
487				meshRenderer.sortingLayerName = tileLayerName;
488				break;
489			}
490			return new Tuple<MeshFilter, MeshRenderer>(meshFilter, meshRenderer);
491		}
492		public static int[] InitTriangles(int tileCount, int indexOffset = 0)
493		{
494			int[] array = new int[tileCount * 3 * 2];
495			int num = indexOffset;
496			for (int i = 0; i < tileCount; i++)
497			{
498				array[i * 6] = num;
499				array[i * 6 + 1] = num + 1;
500				array[i * 6 + 2] = num + 2;
501				array[i * 6 + 3] = num + 2;
502				array[i * 6 + 4] = num + 1;
503				array[i * 6 + 5] = num + 3;
504				num += 4;
505			}
506			return array;
507		}
508		public static void InitSubMeshTriangles(Dictionary<string, List<int>> subMeshIndices, Dictionary<string, List<int>> subMeshTriangles)
509		{
510			foreach (KeyValuePair<string, List<int>> subMeshIndex in subMeshIndices)
511			{
512				for (int i = 0; i < subMeshIndex.Value.Count; i++)
513				{
514					if (!subMeshTriangles.ContainsKey(subMeshIndex.Key))
515					{
516						subMeshTriangles[subMeshIndex.Key] = new List<int>();
517					}
518					subMeshTriangles[subMeshIndex.Key].AddRange(InitTriangles(1, subMeshIndex.Value[i]));
519				}
520			}
521		}
522		public static Vector2[] InitUVs(TileGrid tileGrid, string tileLayerName, string forceTileSet = "")
523		{
524			List<Vector2> list = new List<Vector2>();
525			for (int i = 0; i < tileGrid.RowCount; i++)
526			{
527				for (int j = 0; j < tileGrid.ColCount; j++)
528				{
529					if (!TileGrid.SkipTile(tileGrid[i, j], tileLayerName))
530					{
531						Tile tile = tileGrid[i, j];
532						TileSet tileSet = ((!(forceTileSet != string.Empty)) ? TileSet.GetTileSet(tile.layers[tileLayerName].tileSetName) : TileSet.GetTileSet(forceTileSet));
533						Vector2 tilePositionInGrid = tileSet.GetTilePositionInGrid(tile, tileLayerName, i, j, tileGrid);
534						Vector2[] array = tileSet.GetUVFromTilePosition(tilePositionInGrid);
535						if (tile.layers[tileLayerName].flipX)
536						{
537							array = new Vector2[4]
538							{
539								array[2],
540								array[3],
541								array[0],
542								array[1]
543							};
544						}
545						if (tile.layers[tileLayerName].flipY)
546						{
547							array = new Vector2[4]
548							{
549								array[1],
550								array[0],
551								array[3],
552								array[2]
553							};
554						}
555						list.AddRange(array);
556					}
557				}
558			}
559			return list.ToArray();
560		}
561		public static Vector3[] InitNormals(int vertexCount)
562		{
563			Vector3[] array = new Vector3[vertexCount];
564			for (int i = 0; i < vertexCount; i++)
565			{
566				ref Vector3 reference = ref array[i];
567				reference = Vector3.back;
568			}
569			return array;
570		}
571		public static Color[] InitColors(int vertexCount, TileGrid tileGrid, string tileLayerName)
572		{
573			Color[] array = new Color[vertexCount];
574			for (int i = 0; i < vertexCount; i++)
575			{
576				ref Color reference = ref array[i];
577				reference = new Color(1f, 1f, 1f);
578			}
579			if (tileLayerName != "Overlay")
580			{
581				return array;
582			}
583			int num = 0;
584			Color color = new Color(1f, 1f, 1f, 0.66f);
585			for (int j = 0; j < tileGrid.RowCount; j++)
586			{
587				for (int k = 0; k < tileGrid.ColCount; k++)
588				{
589					Tile tile = tileGrid[j, k];
590					if (!TileGrid.SkipTile(tile, tileLayerName))
591					{
592						num++;
593						if (tile.overlay == Tile.OverlayType.BottomWall || tile.overlay == Tile.OverlayType.TopLeftWall || tile.overlay == Tile.OverlayType.TopRightWall)
594						{
595							int num2 = (num - 1) * 4;
596							array[num2 + 2] = color;
597							array[num2] = color;
598							ref Color reference2 = ref array[num2 + 3];
599							reference2 = Color.white;
600							ref Color reference3 = ref array[num2 + 1];
601							reference3 = Color.white;
602						}
603					}
604				}
605			}
606			return array;
607		}
608	}
