1609		public static Node GetClosestNode(Vector2 position, Dictionary<Vector2, Node> givenMap, int layerMask)
1610		{
1611			intPosition = position;
1612			intPosition.x = Mathf.RoundToInt(position.x);
1613			intPosition.y = Mathf.RoundToInt(position.y);
1614			if (givenMap.ContainsKey(intPosition))
1615			{
1616				return givenMap[intPosition];
1617			}
1618			currentDist = 0f;
1619			minDist = 9999f;
1620			closestVector = -Vector2.one;
1621			foreach (KeyValuePair<Vector2, Node> item in givenMap)
1622			{
1623				if (!Entity.HasLineOfSight(position, item.Key, maxDistBetweenNodes, layerMask))
1624				{
1625					continue;
1626				}
1627				currentDist = Vector2.Distance(item.Key, position);
1628				if (currentDist < minDist)
1629				{
1630					minDist = currentDist;
1631					closestVector = item.Key;
1632					if (minDist < minDistanceStartPoint)
1633					{
1634						break;
1635					}
1636				}
1637			}
1638			return (!givenMap.ContainsKey(closestVector)) ? null : givenMap[closestVector];
1639		}
1640		public static void RemoveNode(Node node, Dictionary<Vector2, Node> givenMap)
1641		{
1642			if (givenMap.ContainsKey(node.coordinate))
1643			{
1644				for (int num = node.connectedNodes.Count - 1; num >= 0; num--)
1645				{
1646					node.connectedNodes[num].connectedNodes.Remove(node);
1647				}
1648				givenMap.Remove(node.coordinate);
1649			}

