1787					{
1788						List<IntPoint> list2 = new List<IntPoint>();
1789						list2.Add(new IntPoint(tile.vertices[0].x, tile.vertices[0].y));
1790						list2.Add(new IntPoint(tile.vertices[1].x, tile.vertices[1].y));
1791						list2.Add(new IntPoint(tile.vertices[3].x, tile.vertices[3].y));
1792						list2.Add(new IntPoint(tile.vertices[2].x, tile.vertices[2].y));
1793						list.Add(list2);
