1795				}
1796			}
1797			list = Clipper.SimplifyPolygons(list);
1798			List<List<Vector2>> list3 = new List<List<Vector2>>();
1799			foreach (List<IntPoint> item2 in list)
1800			{
1801				List<Vector2> list4 = new List<Vector2>();
