1805					list4.Add(item);
1806				}
1807				list3.Add(list4);
1808			}
1809			polygonCollider2D.pathCount = list3.Count;
1810			for (int m = 0; m < list3.Count; m++)
1811			{
1812				polygonCollider2D.SetPath(m, list3[m].ToArray());
1813			}
1814			gameObject2.transform.DestroyChildren(destroyImmediate: true, string.Empty);
1815			GameObject gameObject3 = Object.Instantiate(gameObject2, gameObject2.transform.position, Quaternion.identity);
1816			gameObject3.transform.SetParent(gameObject2.transform);
